/* Fleet day row builder (design.md action-row "date-keyed row").
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Normalized from parking-manager's
 * `day-row.js`, which one renderer served for Home's coming days, a live view
 * and a holidays list. What a row says (title, meta, exception) is the caller's;
 * this file only draws it.
 *
 * Pairs with day-row.css and action-row/action-row.css, and needs the icons
 * sprite on the page for the chevron. Every string goes in with `textContent`,
 * never as HTML.
 */

'use strict';

import { icon } from '../icons/icons.js';

// The tones the chip colours (design.md "status chip"); anything else is a
// plain count chip, never a state.
const TONES = ['danger', 'attention', 'accent'];

const ISO_DAY = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Parse an ISO date as a local calendar day (never `new Date('YYYY-MM-DD')`,
 * which is UTC and shifts the day west of Greenwich).
 *
 * @param {string} day  'YYYY-MM-DD'.
 * @returns {Date} local midnight of that day.
 * @throws {RangeError} when `day` is not a real calendar date.
 */
function parseDay(day) {
  const m = ISO_DAY.exec(day);
  const d = m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
  if (!d || d.getMonth() !== Number(m[2]) - 1 || d.getDate() !== Number(m[3])) {
    throw new RangeError('dayRow: day must be a real YYYY-MM-DD date, got ' + String(day));
  }
  return d;
}

/**
 * Build one day row, an `li.action-row.day-row` for a `ul.action-rows`.
 *
 * @param {object} o
 * @param {string} o.day        ISO date (YYYY-MM-DD), kept as `data-day`.
 * @param {string} o.title      what the day IS ("Booked", "Holiday"), one line.
 * @param {string} [o.status]   kept as `data-status`, an app hook; never styled.
 * @param {string} [o.meta]     why: one line, ellipsized; omitted when empty.
 * @param {{text: string, tone?: string}|null} [o.exception]  the chip, for an
 *        exception only; `tone` is danger | attention | accent, else a plain count.
 * @param {boolean} [o.today]   tints the date tile and marks it `aria-current`.
 * @param {Function} [o.onOpen] makes the row a button, adds the chevron, and is
 *        called with the row on click, Enter or Space.
 * @param {string} [o.locale]   BCP 47 tag for the weekday and the spoken date;
 *        the browser's own when omitted.
 * @returns {HTMLLIElement}
 */
export function dayRow(o) {
  const d = parseDay(o.day);
  const row = document.createElement('li');
  row.className = 'action-row day-row';
  row.dataset.day = o.day;
  if (o.status) row.dataset.status = o.status;

  // A real <button> when the row opens something (Enter and Space for free), a
  // plain <div> when it only reads.
  const main = document.createElement(o.onOpen ? 'button' : 'div');
  main.className = 'action-row-main day-row-main' + (o.onOpen ? '' : ' day-row-main--static');
  if (o.onOpen) main.type = 'button';
  if (o.today) main.setAttribute('aria-current', 'date');

  const tile = document.createElement('span');
  tile.className = 'date-tile' + (o.today ? ' is-today' : '');
  const spoken = document.createElement('span');
  spoken.className = 'date-tile-sr';
  spoken.textContent = new Intl.DateTimeFormat(o.locale, {
    weekday: 'long', day: 'numeric', month: 'long',
  }).format(d);
  const dow = document.createElement('span');
  dow.className = 'date-tile-dow';
  dow.setAttribute('aria-hidden', 'true');
  dow.textContent = new Intl.DateTimeFormat(o.locale, { weekday: 'short' }).format(d);
  const num = document.createElement('span');
  num.className = 'date-tile-num';
  num.setAttribute('aria-hidden', 'true');
  num.textContent = String(d.getDate());
  tile.append(spoken, dow, num);

  const text = document.createElement('span');
  text.className = 'action-row-text';
  const title = document.createElement('span');
  title.className = 'action-row-title';
  title.textContent = o.title;
  title.title = o.title;
  text.appendChild(title);
  if (o.meta) {
    const meta = document.createElement('span');
    meta.className = 'action-row-meta';
    meta.textContent = o.meta;
    meta.title = o.meta;
    text.appendChild(meta);
  }
  main.append(tile, text);

  if (o.exception && o.exception.text) {
    const chip = document.createElement('span');
    chip.className = 'day-row-chip';
    if (TONES.indexOf(o.exception.tone) !== -1) chip.dataset.tone = o.exception.tone;
    chip.textContent = o.exception.text;
    main.appendChild(chip);
  }
  if (o.onOpen) {
    main.insertAdjacentHTML('beforeend', icon('chevron-right', 'day-row-chevron'));
    main.addEventListener('click', function () { o.onOpen(row); });
  }

  row.appendChild(main);
  return row;
}
